package tweaks

// Texto en inglés de cada ajuste: {nombre, descripción, advertencia, protección anti-cheat}.
// Si falta una entrada se muestra el texto en español (hay una prueba que lo evita).

const appsNote = " It is removed only for your user. When reverting, restoration is attempted and, if that is not possible, it is reinstalled from the Microsoft Store."

// EnText es la traducción de un ajuste.
type EnText struct{ Name, Desc, Warn, AC string }

// EnCategory es la traducción de una categoría.
type EnCategory struct{ Name, Desc string }

// English devuelve la traducción de un ajuste.
func English(id string) (EnText, bool) { t, ok := enCatalog[id]; return t, ok }

// EnglishCategory devuelve la traducción de una categoría.
func EnglishCategory(id string) (EnCategory, bool) { c, ok := enCategories[id]; return c, ok }

var enCategories = map[string]EnCategory{
	"fps":      {"FPS and games", "Direct tweaks to gain frames"},
	"latency":  {"Latency and input", "Mouse, keyboard and timers"},
	"gpu":      {"Graphics", "Graphics card and DWM options"},
	"power":    {"Power and CPU", "Power plan and processor states"},
	"memory":   {"Memory and disk", "RAM, SSD and file system"},
	"network":  {"Network and ping", "Lower latency online"},
	"services": {"Services", "Windows services you do not need"},
	"privacy":  {"Privacy", "Telemetry and tracking"},
	"debloat":  {"Windows 11 debloat", "Removes ads, widgets and filler"},
	"apps":     {"Preinstalled apps", "Uninstall apps you do not use"},
	"ui":       {"Interface and effects", "Animations and visual effects"},
	"advanced": {"Advanced (risk)", "Only if you know what you are doing"},
}

